    (dm_get(&dm, "FacesDetected").is_some_and(|v| v >= 2.0)
        || (dm_get(&dm, "FacesDetected").is_some_and(|v| v == 1.0)
            && dm_get(&dm, "FaceTest8").is_some_and(|v| v > 0.0)))
